import re

base64_data = ""

icon_tags = f'''  <link rel="icon" type="image/png" href="data:image/png;base64,{base64_data}">
  <link rel="icon" type="image/svg+xml" href="favicon.svg?v=20260910c">
  <link rel="icon" href="favicon.ico?v=20260910c" sizes="48x48">
  <link rel="icon" type="image/png" sizes="32x32" href="icon-32.png?v=20260910c">'''

with open("/Volumes/NetworkSSD/Anode/privacy.html", "r") as f:
    html = f.read()

html = re.sub(r'  <link rel="icon"[^>]*>(\n  <link rel="[^"]*"[^>]*>)*', icon_tags, html)

with open("/Volumes/NetworkSSD/Anode/privacy.html", "w") as f:
    f.write(html)

print("Updated privacy.html favicons!")
